import {productGallery} from './product-gallery.js';
import {categoryNav as renderCategoryNav,shopMenu,subcategoryFilters} from './category-navigation.js';
import {subcategorySlugs,findSubcategory} from './category-tree.js';
const $=(s,r=document)=>r.querySelector(s);
function cricketGuide(){return `<section class="section cricket-guide"><div class="breadcrumb"><a href="/">Home</a> / About cricket</div><span class="eyebrow">CRICKET CENTRAL</span><h1>About cricket</h1><p class="guide-intro">The pitch, the basics, and a few habits to take into your next practice session.</p><nav class="guide-nav" aria-label="Cricket guide sections"><a href="#cricket-basics">Pitch & rules</a><a href="#cricket-skills">Player tips</a></nav><section id="cricket-basics"><h2>The pitch & basic rules</h2><a class="guide-poster" href="/assets/cricket-pitch-rules.png" target="_blank" rel="noopener"><img src="/assets/cricket-pitch-rules.png" alt="Cricket Central: cricket ground with a 22-yard pitch and beginner scoring rules" width="1536" height="1024"></a><div class="guide-facts"><div><h3>The pitch</h3><p>The wickets stand 22 yards apart on the central pitch.</p></div><div><h3>Runs</h3><p>Batters score by completing runs between the wickets. A boundary normally scores four; a hit over the boundary without bouncing normally scores six.</p></div><div><h3>Overs</h3><p>An over contains six valid deliveries. Wides and no-balls do not count towards those six.</p></div></div><p class="guide-source">Beginner summary. Formats and competition conditions vary. <a href="https://www.lords.org/mcc/the-laws-of-cricket" target="_blank" rel="noopener">Read the MCC Laws of Cricket</a>.</p></section><section id="cricket-skills"><h2>Batting, bowling & fielding</h2><a class="guide-poster" href="/assets/cricket-skills-tips.png" target="_blank" rel="noopener"><img src="/assets/cricket-skills-tips.png" alt="Cricket Central player tips: watch the ball and stay balanced when batting; use a steady run-up and aim for line and length when bowling; stay ready and use soft hands when fielding" width="1536" height="1024" loading="lazy"></a><div class="guide-facts"><div><h3>Batting</h3><ul><li>Watch the ball.</li><li>Keep a balanced stance.</li><li>Practise controlled, straight shots.</li></ul></div><div><h3>Bowling</h3><ul><li>Build a repeatable run-up.</li><li>Practise line and length before adding pace.</li><li>Complete your follow-through.</li></ul></div><div><h3>Fielding</h3><ul><li>Stay alert in a ready position.</li><li>Receive catches with soft hands.</li><li>Back up throws and support teammates.</li></ul></div></div></section></section>`;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
const isOnSale=p=>p.onSale??(p.compareAtPrice>p.price);
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',truck:'<path d="M1 5h13v12H1zM14 9h5l4 5v3h-9"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',return:'<path d="M4 9a8 8 0 1 1 0 8M4 3v6h6"/>',pin:'<path d="M19 9c0 6-7 13-7 13S5 15 5 9a7 7 0 0 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
let store,cart,csrf;let saved=[];
function accountDestination(){const next=new URLSearchParams(location.search).get('next');return next==='checkout'?'/checkout':next==='wishlist'?'/wishlist':next?.startsWith('/products/')&&!/[?#\\\\]/.test(next)?next:'/account';}
let checkoutId=crypto.randomUUID();
const brandLogos=[{"name": "SS", "file": "ss.png"}, {"name": "SF", "file": "sf.png"}, {"name": "SG", "file": "sg.png"}, {"name": "MRF", "file": "mrf.png"}, {"name": "Adidas", "file": "adidas.png"}, {"name": "ASICS", "file": "asics.png"}, {"name": "BAS Vampire", "file": "bas-vampire.png"}, {"name": "CA", "file": "ca.png"}, {"name": "CEAT", "file": "ceat.png"}, {"name": "DSC", "file": "dsc.png"}, {"name": "Duncan Fernley", "file": "duncan-fernley.png"}, {"name": "EM", "file": "em.png"}, {"name": "Forma", "file": "forma.png"}, {"name": "GM", "file": "gm.png"}, {"name": "Gortonshire", "file": "gortonshire.png"}, {"name": "Gray Nicolls", "file": "gray-nicolls.png"}, {"name": "Hammer", "file": "hammer.png"}, {"name": "Kookaburra", "file": "kookaburra.png"}, {"name": "Masuri", "file": "masuri.png"}, {"name": "MB Malik", "file": "mb-malik.png"}, {"name": "Moonwalkr", "file": "moonwalkr.png"}, {"name": "Morrant", "file": "morrant.png"}, {"name": "New Balance", "file": "new-balance.png"}, {"name": "Oakley", "file": "oakley.png"}, {"name": "Omtex", "file": "omtex.png"}, {"name": "Puma", "file": "puma.png"}, {"name": "Reebok", "file": "reebok.png"}, {"name": "Shrey", "file": "shrey.png"}, {"name": "Somi", "file": "somi.png"}, {"name": "Tenxu", "file": "tenxu.png"}, {"name": "TON", "file": "ton.png"}, {"name": "Tyka", "file": "tyka.png"}, {"name": "Versant", "file": "versant.png"}, {"name": "Yonker", "file": "yonker.png"}];
const brandLogo=b=>brandLogos.find(x=>x.name.toLowerCase()===String(b||'').toLowerCase());
const image=p=>{const logo=brandLogo(p.brand);return `<div class="gear-image"><img src="/assets/${esc(p.image)}" alt="${esc(p.name)}" loading="lazy">${logo?`<span class="brand-badge"><img src="/assets/brands/${logo.file}" alt="${esc(logo.name)} logo" loading="lazy"></span>`:''}</div>`;};
async function api(path,method='GET',data){const response=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf||''},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok){if(response.status===401&&path.startsWith('account')&&store){store.user=null;saved=[];}throw Object.assign(Error(result.error||'Please try again.'),{status:response.status});}return result;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function brand(){return '<img class="brand-logo" src="/assets/cricket-central-horizontal.png" alt="Cricket Central">';}
function categoryNavState(slug){return location.pathname==='/collections/'+encodeURIComponent(slug)?' aria-current="page"':'';}
function categoryNav(c){return renderCategoryNav(c,esc,categoryNavState);}
function header(){return `<div class="announcement"><span>GOOD GEAR. GREAT INNINGS.</span><span>Free US shipping on orders $99+ ${icon('arrow')}</span><a href="/track-order">Track your order</a></div><header class="site-header"><a class="brand" href="/" aria-label="Cricket Central home">${brand()}</a><form class="search-form" action="/search"><label class="sr-only" for="header-search">Search products</label>${icon('search')}<input id="header-search" name="q" placeholder="What’s in your kit bag?" value="${esc(new URLSearchParams(location.search).get('q')||'')}"><kbd>SEARCH</kbd></form><div class="header-actions"><a class="account-link" href="/account">${store.user?'My account':'Sign in'}</a><a class="store-link" href="/pages/store">${icon('pin')}<span>Visit the store<small>Columbus, Ohio</small></span></a><a class="icon-button" href="/wishlist" aria-label="Saved items">${icon('heart')}</a><button class="icon-button bag-button" data-action="bag" aria-label="Open shopping bag">${icon('bag')}<span class="cart-count">${cart.count}</span></button></div></header><nav class="nav" aria-label="Shop categories">${shopMenu(store.categories,esc)}${store.categories.map(categoryNav).join('')}<a class="nav-sale" href="/collections/sale"${categoryNavState('sale')}>Sale</a><a href="/pages/brands">Our brands</a><a class="nav-guide" href="/pages/bat-finder">Find your bat ↗</a></nav>`;}
function footer(){return `<section class="newsletter"><div><span class="eyebrow">THE CRICKET CENTRAL CLUB</span><h2>Keep your eye on the ball.</h2><p>New gear, cricket stories, and a little inside knowledge.</p></div><form id="newsletter-form"><label class="sr-only" for="newsletter-email">Email address</label><div><input type="email" id="newsletter-email" name="email" placeholder="Your email address" required maxlength="190"><button aria-label="Join the newsletter">${icon('arrow')}</button></div><small>By subscribing, you agree to our <a href="/pages/privacy">privacy policy</a>. Demo signup; no emails are sent.</small></form></section><footer><div class="footer-main"><div class="footer-intro"><a class="brand" href="/"><img class="brand-logo" src="/assets/cricket-central-horizontal.png" alt="Cricket Central"></a><p>From your first net session to your next century.<br>We’re here for every innings.</p><span class="eyebrow">MADE FOR THE GAME. AND YOU.</span></div><div><h3>Get your gear</h3>${store.categories.map(c=>`<a href="/collections/${encodeURIComponent(c.slug)}">${esc(c.name)}</a>`).join('')}<a href="/collections/all">Shop everything</a><a href="/collections/sale">Shop sale</a></div><div><h3>Here to help</h3><a href="/track-order">Track an order</a><a href="/pages/shipping">Shipping & delivery</a><a href="/pages/returns">Returns & exchanges</a><a href="/pages/size-guide">Size guide</a><a href="/pages/faq">FAQs</a></div><div><h3>Our corner of cricket</h3><a href="/pages/about">Our story</a><a href="/pages/cricket-guide">About cricket</a><a href="/pages/store">Visit the store</a><a href="/pages/contact">Get in touch</a><a href="/pages/bat-finder">Bat finder</a><a href="/pages/brands">Our brands</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Cricket Central. All innings welcome.</span><div><a href="/pages/privacy">Privacy</a><a href="/pages/terms">Terms</a><span>United States · USD $</span></div></div></footer>`;}
function productBadges(p){const discount=p.compareAtPrice>p.price?Math.round((1-p.price/p.compareAtPrice)*100):0;const onSale=isOnSale(p);return `<div class="item-badges">${p.isNew?'<span class="item-badge new">New</span>':''}${onSale?`<span class="item-badge sale">Sale${p.discountType==='fixed'&&discount>0?` · Save ${money(p.discountValue)}`:discount>0?` · Save ${discount}%`:''}</span>`:''}</div>`;}
function card(p){return `<article class="product-card"><div class="product-visual"><a href="/products/${p.slug}">${image(p)}</a>${productBadges(p)}<button class="save-button ${saved.includes(p.id)?'selected':''}" data-action="save" data-id="${p.id}" aria-label="Save ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button><a class="quick-shop" href="/products/${p.slug}">Choose options ${icon('arrow')}</a></div><div class="product-meta"><span>${esc(p.brand)}</span><span>${esc(p.sku)}</span></div><h3><a href="/products/${p.slug}">${esc(p.name)}</a></h3><div class="price-row">${p.compareAtPrice>p.price?`<del aria-label="Original price">${money(p.compareAtPrice)}</del>`:''}<strong>${money(p.price)}</strong></div><span class="card-stock">${p.stock?'In stock':'Sold out'}</span></article>`;}

function home(){return `${homeBanner()}<section class="benefits" aria-label="Shopping benefits"><div>${icon('truck')}<span><b>On us, from $99</b><small>Free shipping across the US</small></span></div><div>${icon('shield')}<span><b>Gear you can trust</b><small>Equipment from trusted brands</small></span></div><div>${icon('return')}<span><b>Find the right fit</b><small>Helpful sizing & gear guides</small></span></div><div>${icon('pin')}<span><b>Your local cricket people</b><small>Come say hello in Columbus</small></span></div></section><section class="section categories-section" id="shop-categories"><div class="section-heading"><div><span class="eyebrow">BUILD YOUR KIT</span><h2>Every player. Every position.</h2></div><a class="underlined" href="/collections/all">Shop all gear ${icon('arrow')}</a></div><div class="category-grid">${store.categories.map((c,i)=>`<a class="category-card" href="/collections/${encodeURIComponent(c.slug)}"><span class="category-number">${String(i+1).padStart(2,'0')}</span>${image(c)}<span>${esc(c.name)} ${icon('arrow')}</span></a>`).join('')}</div></section><section class="section brand-showcase" aria-labelledby="brands-heading"><div class="section-heading"><div><span class="eyebrow">BIG NAMES. BIG GAME.</span><h2 id="brands-heading">Explore our brands.</h2></div><div class="brand-controls"><button type="button" data-brand-step="-1" aria-label="Previous brands" aria-controls="brand-track">←</button><button type="button" id="brand-pause" aria-label="Pause automatic brand scrolling">Pause</button><button type="button" data-brand-step="1" aria-label="Next brands" aria-controls="brand-track">→</button></div></div><div class="brand-logo-grid" id="brand-track" tabindex="0" aria-label="Brand logos">${brandLogos.map(b=>`<a href="/collections/all?brand=${encodeURIComponent(b.name)}" aria-label="Shop ${esc(b.name)}"><img src="/assets/brands/${b.file}" alt="${esc(b.name)}" loading="lazy" width="150" height="80"></a>`).join('')}</div></section><section class="section featured-section"><div class="section-heading"><div><span class="eyebrow">THE GOOD STUFF</span><h2>Ready for your starting XI.</h2><p>Our team’s picks for your next match day.</p></div><a class="underlined" href="/collections/all">Explore the collection ${icon('arrow')}</a></div><div class="product-grid">${store.products.filter(p=>p.featured).map(card).join('')}</div></section><section class="editorial"><div class="finder-copy"><span class="eyebrow">A GOOD INNINGS STARTS HERE</span><h2>The right bat.<br>A different game.</h2><p>Big hitter or touch player? First season or club regular? Let’s find the bat that feels like you.</p><a class="button dark" href="/pages/bat-finder">Find my bat ${icon('arrow')}</a><span class="finder-note">A few questions. Your next favorite bat.</span></div><div class="finder-art"><span class="giant-number">01</span><div class="bat-shape one"></div><div class="bat-shape two"></div><span>FIND YOUR<br>SWEET SPOT.</span></div></section><section class="section community"><div class="community-art"><img src="/assets/about-reference.jpg" alt="Cricket Central store and cricket community" loading="lazy"><span>YOUR GAME.<br>OUR COMMUNITY.</span></div><div class="community-copy"><span class="eyebrow">MORE THAN A CRICKET STORE</span><h2>For the players.<br>By cricket people.</h2><p>We know that feeling. The first crack off a new bat. A clean catch. A game that comes down to the final ball.</p><p>Cricket Central is a place for people who love it all. Discover equipment, find your fit, and make yourself at home.</p><a class="underlined" href="/pages/about">Get to know us ${icon('arrow')}</a></div></section>`;}
function collection(){const params=new URLSearchParams(location.search),slug=location.pathname.split('/').pop(),q=params.get('q')||'',brand=params.get('brand')||'',sub=params.get('sub')||'',sort=params.get('sort')||'featured',max=Number(params.get('max'))||Math.max(1000,...store.products.map(p=>Math.ceil(p.price/100)));const sale=slug==='sale';const cat=store.categories.find(c=>c.slug===slug),selectedSubs=subcategorySlugs(cat?.subcategories,sub);let rows=store.products.filter(p=>(sale?isOnSale(p):(!cat||p.category===slug))&&(!sub||selectedSubs.has(p.subcategory))&&(!brand||p.brand===brand)&&p.price<=max*100&&(!q||`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(q.toLowerCase())));if(sort==='low')rows.sort((a,b)=>a.price-b.price);else if(sort==='high')rows.sort((a,b)=>b.price-a.price);else if(sort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));else rows.sort((a,b)=>Number(b.featured)-Number(a.featured));return `<section class="collection-top"><div class="breadcrumb"><a href="/">Home</a> / ${sale?'Sale':q?'Search':cat?esc(cat.name):'All gear'}</div><span class="eyebrow">YOUR NEXT INNINGS STARTS HERE</span><h1>${sale?'Cricket gear on sale.':location.pathname==='/search'?`Results for “${esc(q)}”`:cat?esc(findSubcategory(cat.subcategories,sub)?.name||cat.name):'All the gear. All the game.'}</h1><p>${sale?'Shop every current sale, with percentage and fixed-dollar savings.':'Find your match-day essentials, from the first ball to the last.'}</p></section><section class="section collection-layout"><aside class="filters"><div class="filter-heading"><h2>Find your gear</h2><a href="${location.pathname}">Reset</a></div><h3>Categories</h3><a class="${!cat&&!sale?'active':''}" href="/collections/all">All cricket gear <span>${store.products.length}</span></a><a class="${sale?'active':''}" href="/collections/sale">Sale <span>${store.products.filter(isOnSale).length}</span></a>${store.categories.map(c=>`<a class="${c.slug===slug&&!sub?'active':''}" href="/collections/${encodeURIComponent(c.slug)}">${esc(c.name)}<span>${store.products.filter(p=>p.category===c.slug).length}</span></a>${c.slug===slug?subcategoryFilters(c,sub,store.products,esc):''}`).join('')}<form id="filters-form"><h3>Brand</h3><select aria-label="Filter by brand" name="brand"><option value="">All brands</option>${[...new Set(store.products.map(p=>p.brand))].sort().map(b=>`<option ${b===brand?'selected':''}>${b}</option>`).join('')}</select><h3>Price range</h3><label for="max-price">Maximum price (USD)</label><input id="max-price" aria-label="Maximum price in USD" type="number" name="max" min="1" max="100000" value="${max}"><input type="hidden" name="sort" value="${esc(sort)}">${sub?`<input type="hidden" name="sub" value="${esc(sub)}">`:''}${q?`<input type="hidden" name="q" value="${esc(q)}">`:''}<button class="button dark">Apply filters ${icon('arrow')}</button></form></aside><div><div class="sort-row"><span><b>${rows.length}</b> products ${brand?`· ${esc(brand)}`:''}</span><label>Sort by <select id="sort"><option value="featured" ${sort==='featured'?'selected':''}>Featured</option><option value="low" ${sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${sort==='high'?'selected':''}>Price: high to low</option><option value="name" ${sort==='name'?'selected':''}>Name: A to Z</option></select></label></div>${rows.length?`<div class="product-grid collection-products">${rows.map(card).join('')}</div>`:`<div class="empty-state">${icon('search')}<h2>${sale?'No sale items found.':'No gear found this time.'}</h2><p>${sale?'Clear your filters or check back soon for new offers.':'Try another search or clear your filters.'}</p><a class="button dark" href="/collections/all">Explore all gear ${icon('arrow')}</a></div>`}</div></section>`;}
function product(){const p=store.products.find(p=>p.slug===location.pathname.split('/').pop());if(!p)return notFound();return `<section class="section"><div class="breadcrumb"><a href="/">Home</a> / <a href="/collections/${p.category}">${esc(store.categories.find(c=>c.slug===p.category)?.name||'All gear')}</a> / ${esc(p.name)}</div><div class="product-detail"><div class="detail-image">${productGallery(p,icon,esc)}${productBadges(p)}</div><div class="product-info"><span class="eyebrow">${esc(p.brand)} / MATCH DAY READY</span><h1>${esc(p.name)}</h1><div class="detail-price">${p.compareAtPrice>p.price?`<del aria-label="Original price">${money(p.compareAtPrice)}</del> `:''}${money(p.price)}<span class="stock-dot">${p.stock?'In stock':'Sold out'}</span></div><p>${esc(p.description)}</p><form id="product-form" data-id="${p.id}"><fieldset><legend>Select your option</legend><div class="option-grid">${p.options.map((o,i)=>`<label><input type="radio" name="option" value="${esc(o)}" ${i===0?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div></fieldset><a class="size-link" href="/pages/size-guide">Need a hand? View the size guide ↗</a><div class="add-row"><label class="quantity-control"><span class="sr-only">Quantity</span><input type="number" name="quantity" value="1" min="1" max="${p.stock}" required></label><button class="button dark" ${!p.stock?'disabled':''}>${p.stock?'Add to bag':'Sold out'} ${icon('bag')}</button><button type="button" class="icon-button ${saved.includes(p.id)?'selected':''}" data-action="save" data-id="${p.id}" aria-label="Save item" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button></div></form><div class="product-perks"><span>${icon('truck')} Free shipping on orders $99+</span><span>${icon('shield')} Carefully selected cricket equipment</span></div><details open><summary>Product overview</summary><p class="product-copy">${esc(p.overview||p.description)}</p></details><details open><summary>Key Features</summary><ul>${(p.keyFeatures||p.description).split(/\n+/).filter(Boolean).map(feature=>`<li>${esc(feature)}</li>`).join('')}</ul></details><details open><summary>Additional Information</summary><p class="product-copy">${esc(p.additionalInformation||'')}</p><dl><dt>Brand</dt><dd>${esc(p.brand)}</dd><dt>SKU</dt><dd>${esc(p.sku)}</dd><dt>Available</dt><dd>${p.stock} units</dd></dl></details><details><summary>Shipping & returns</summary><p>Estimated US shipping is $9.99, or free on orders $99+. Our team confirms fulfillment and final charges before payment. <a href="/pages/returns">Read our return guidance.</a></p></details></div></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">COMPLETE YOUR KIT</span><h2>Good company for your gear.</h2></div></div><div class="product-grid">${store.products.filter(x=>x.id!==p.id&&(x.category===p.category||x.featured)).slice(0,4).map(card).join('')}</div></section>`;}
function cartItems(){return cart.items.map(i=>`<div class="cart-item">${image(i)}<div><a href="/products/${i.slug}"><b>${esc(i.name)}</b></a><small>${esc(i.option)}</small><div class="cart-item-bottom"><div class="stepper"><button data-action="quantity" data-key="${esc(i.key)}" data-value="${i.quantity-1}" aria-label="Decrease quantity">−</button><span>${i.quantity}</span><button data-action="quantity" data-key="${esc(i.key)}" data-value="${i.quantity+1}" aria-label="Increase quantity">+</button></div><button class="remove" data-action="quantity" data-key="${esc(i.key)}" data-value="0">Remove</button><strong>${money(i.price*i.quantity)}</strong></div></div></div>`).join('');}
function totals(){return `<div class="summary-line"><span>Subtotal</span><b>${money(cart.subtotal)}</b></div><div class="summary-line"><span>Estimated shipping</span><b>${cart.shipping?money(cart.shipping):'On us'}</b></div><div class="summary-line"><span>Tax</span><b>Confirmed by our team</b></div>${cart.discount?`<div class="summary-line"><span>Discount (${esc(cart.promotion)})</span><b>−${money(cart.discount)}</b></div>`:''}<div class="summary-line total"><span>Estimated total</span><b>${money(cart.total)}</b></div>`;}
function emptyBag(){return `<div class="empty-state">${icon('bag')}<h2>Your next innings starts here.</h2><p>Your bag is empty. Let’s find your gear.</p><a class="button dark" href="/collections/all">Explore the store ${icon('arrow')}</a></div>`;}
function cartPage(){return `<section class="section"><span class="eyebrow">YOUR MATCH DAY LINEUP</span><h1>Your kit bag <small>(${cart.count})</small></h1>${cart.items.length?`<div class="cart-layout"><div>${cartItems()}</div><aside class="order-summary"><h2>The scorecard</h2>${totals()}<a class="button dark" href="/checkout">Continue to checkout ${icon('arrow')}</a><p class="muted">Demo checkout · no payment collected</p></aside></div>`:emptyBag()}</section>`;}
function openBag(){const dialog=$('#bag');dialog.innerHTML=`<div class="bag-heading"><h2 id="bag-title">Your kit bag <small>(${cart.count})</small></h2><button class="icon-button" data-action="close-bag" aria-label="Close bag">${icon('close')}</button></div>${cart.items.length?`<div class="shipping-message">${cart.subtotal>=9900?'You’ve unlocked free shipping.':`You’re ${money(9900-cart.subtotal)} away from free shipping.`}</div><div class="bag-items">${cartItems()}</div><div class="bag-summary">${totals()}<a class="button dark" href="/checkout">Checkout ${icon('arrow')}</a><a class="view-bag" href="/cart">View your bag</a><small>Demo store · no payment collected</small></div>`:emptyBag()}`;if(!dialog.open)dialog.showModal();}
function checkout(){
 if(!cart.items.length)return `<section class="section">${emptyBag()}</section>`;
 const u=store.user||{},names=(u.name||'').trim().split(/\s+/),firstName=names.shift()||'',lastName=names.join(' ');
 return `<section class="section checkout-section"><div class="breadcrumb"><a href="/cart">Your bag</a> / Checkout</div><h1>Submit your order.</h1><div class="checkout-account">${store.user?`Signed in as <b>${esc(u.email)}</b>. Track this order in your account.`:`Checking out as a guest. <a href="/account/login?next=checkout">Sign in</a> or <a href="/account/register?next=checkout">create an account</a> to keep your orders together.`}</div><div class="demo-notice"><b>Our team will contact you.</b> Submit your order request and we’ll confirm availability, final charges and payment. No payment is collected on this website.</div><form id="promotion-form"><label>Discount code<input name="code" value="${esc(cart.promotion||'')}" maxlength="30"></label><p class="form-error"></p><button class="button dark">Apply code</button></form><form id="checkout-form" class="checkout-layout"><div><h2>01 / Contact details</h2><label>Email address<input type="email" name="email" autocomplete="email" required maxlength="190" value="${esc(u.email||'')}" ${store.user?'readonly':''}></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" value="${esc(u.phone||'')}" maxlength="25" required></label><div class="form-grid"><label>First name<input name="firstName" autocomplete="given-name" value="${esc(firstName)}" required maxlength="100"></label><label>Last name<input name="lastName" autocomplete="family-name" value="${esc(lastName)}" required maxlength="100"></label></div><h2>02 / Delivery address</h2><label>Street address<input name="address" autocomplete="street-address" value="${esc(u.address||'')}" required maxlength="190"></label><div class="form-grid"><label>City<input name="city" autocomplete="address-level2" value="${esc(u.city||'')}" required maxlength="100"></label><label>State<input name="state" autocomplete="address-level1" value="${esc(u.state||'')}" required maxlength="100"></label><label>ZIP code<input name="zip" autocomplete="postal-code" value="${esc(u.zip||'')}" pattern="[0-9]{5}(-[0-9]{4})?" required></label><label>Country<input value="United States" disabled></label></div><h2>03 / Review and submit</h2><p>Check your items and contact details. Our team will arrange payment with you after confirming the order.</p><p class="form-error" role="alert"></p><button class="button dark">Submit order · ${money(cart.total)} ${icon('arrow')}</button><p class="muted">Estimated total; any applicable tax and final delivery charges will be confirmed by our team before payment.</p></div><aside class="order-summary"><h2>Your lineup</h2>${cart.items.map(i=>`<div class="checkout-item">${image(i)}<div><b>${esc(i.name)}</b><small>${esc(i.option)} · Qty ${i.quantity}</small></div><strong>${money(i.price*i.quantity)}</strong></div>`).join('')}${totals()}<a class="underlined" href="/cart">Edit your bag</a></aside></form></section>`;
}
function recoveryPage(){const reset=location.pathname.endsWith('reset-password');return `<section class="section narrow"><h1>${reset?'Choose a new password.':'Reset your password.'}</h1><form id="recovery-form" data-mode="${reset?'reset-password':'forgot-password'}">${reset?'<label>New password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label>':'<label>Email<input name="email" type="email" autocomplete="email" required></label>'}<p class="form-error" role="status"></p><button class="button dark">${reset?'Reset password':'Email reset link'}</button></form><p><a href="/account/login">Back to sign in</a></p></section>`;}

function orderView(o){return `<div class="order-result"><span class="status-pill">${esc(o.status)}</span><h2>${esc(o.number)}</h2><p>${new Date(o.created).toLocaleDateString('en-US',{dateStyle:'long'})} · ${esc(o.paymentStatus)}</p>${o.items.map(i=>`<div class="summary-line"><span>${esc(i.name)} × ${i.quantity}</span><b>${money(i.price*i.quantity)}</b></div>`).join('')}<div class="summary-line total"><span>Total</span><b>${money(o.total)}</b></div>${o.fulfillment?.trackingNumber?`<p>Shipment: ${esc(o.fulfillment.carrier)} · ${esc(o.fulfillment.trackingNumber)}</p>`:''}${orderTimeline(o)}<p>Our team will contact you to confirm the order and arrange payment.</p></div>`;}
function tracking(){const order=new URLSearchParams(location.search).get('order')||'';return `<section class="section narrow"><span class="eyebrow">FOLLOW YOUR INNINGS</span><h1>Track your order.</h1><p>Guests can track using the order number and checkout email. <a class="underlined" href="/account">Sign in to view all your orders.</a></p><form id="track-form"><label>Order number<input name="number" placeholder="CC-…" value="${esc(order)}" required></label><label>Email address<input name="email" type="email" required></label><p class="form-error" role="alert"></p><button class="button dark">Find my order ${icon('arrow')}</button></form><div id="tracking-result" aria-live="polite"></div></section>`;}
function finder(){return `<section class="section narrow"><span class="eyebrow">FIND YOUR SWEET SPOT</span><h1>A bat that feels like you.</h1><p>Tell us a little about your game. We’ll point you toward your next bat.</p><form id="finder-form"><label>Who’s playing?<select name="player"><option value="adult">Adult player</option><option value="junior">Junior player</option></select></label><label>Your style of play<select name="style"><option value="balanced">Timing & all-round play</option><option value="power">Power hitting</option></select></label><label>Your budget<select name="budget"><option value="350">Up to $350</option><option value="300">Up to $300</option><option value="500">Up to $500</option></select></label><button class="button dark">Show my matches ${icon('arrow')}</button></form><div id="finder-result" aria-live="polite"></div></section>`;}
const pages={about:['Our story.','Cricket belongs to everyone.','From weekend matches to evening nets, cricket creates connections. Cricket Central brings together gear for players at every stage of their game.','Our collection covers bats, protection, clothing, footwear, and training equipment. We want every player to feel ready when they step onto the field.'],store:['Your local cricket corner.','Columbus, Ohio','The original project lists Cricket Central at Rangoli Mall in Columbus. Store hours, the full street address, and pickup availability still need to be confirmed before launch.','Explore the catalog online while those details are being prepared.'],contact:['Let’s talk cricket.','Need a hand with your gear?','Start with our bat finder, sizing guide, and product details to build your kit. For an existing order, use order tracking with your order number and email.','Contact orders@cricketcentral.us for order support.'],shipping:['From our kit bag to yours.','Shipping & delivery','This preview calculates a flat $9.99 shipping charge for US orders below $99. Orders of $99 or more qualify for free estimated shipping.','Our team confirms delivery arrangements, applicable taxes and final charges before collecting payment.'],returns:['Let’s get the fit right.','Returns & exchanges','Contact our team to confirm return and exchange eligibility before arranging payment.','Before choosing equipment, check your size and selected hand. Bat preparation, used equipment, and personalized items may require special return terms in the final policy.'],privacy:['Your details, handled with care.','Preview privacy information','We store account information, submitted order details and saved favorites to provide this service. A session cookie connects you to your account and shopping bag.','We do not collect card details on this website. Contact orders@cricketcentral.us with questions about your account data.'],terms:['The rules of play.','Ordering information','Orders submitted here are requests for confirmation by our team. Availability, final charges and payment arrangements are confirmed before processing.','No payment is collected online. Our team will contact you using the details supplied at checkout.']};
function page(){const slug=location.pathname.split('/').pop();if(slug==='cricket-guide')return cricketGuide();if(slug==='bat-finder')return finder();if(slug==='brands')return `<section class="section"><span class="eyebrow">THE NAMES IN YOUR KIT</span><h1>Big names. Big game.</h1><div class="brands-grid">${[...new Set(store.products.map(p=>p.brand))].map(b=>`<a href="/collections/all?brand=${encodeURIComponent(b)}">${esc(b)} ${icon('arrow')}</a>`).join('')}</div></section>`;if(slug==='size-guide')return `<section class="section narrow"><span class="eyebrow">FEEL GOOD. PLAY BETTER.</span><h1>Find your fit.</h1><p>Use this as a starting point. Fit varies by brand; check the manufacturer’s measurements before purchasing.</p><details open><summary>Cricket bats</summary><p>Junior players should choose a bat they can lift comfortably into their stance. Most adult players begin with a short handle. Taller players may prefer a long handle. Weight and pickup matter as much as length.</p></details><details open><summary>Gloves & pads</summary><p>Select the hand you bat with. Try protective gear in your batting stance and check that straps secure it comfortably without restricting movement.</p></details><details open><summary>Helmets & footwear</summary><p>Measure around the widest part of your head and compare with the specific manufacturer’s chart. Helmet fit and safety certification must be verified. Shoes in this demo use US sizing.</p></details><a class="button dark" href="/pages/bat-finder">Try the bat finder ${icon('arrow')}</a></section>`;if(slug==='faq')return `<section class="section narrow"><span class="eyebrow">A LITTLE INSIDE KNOWLEDGE</span><h1>Good questions.</h1>${[['Can I buy gear here?','Submit an order request online. Our team will contact you to confirm availability, final charges and payment.'],['Where is my order?','Use the Track your order page with your order number and checkout email. Your order’s current processing status appears there.'],['How much is delivery?','Estimated US shipping is $9.99, or free when your subtotal reaches $99.'],['How do I choose a bat?','Try our bat finder to compare products by player type, style, and budget.'],['Can I save products?','Use the heart on any product card. Sign in, then use a product’s heart to save it to your account. View your favorites from the heart in the header or My account.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`;const p=pages[slug];if(!p)return notFound();return `<section class="section story-page"><div><span class="eyebrow">CRICKET CENTRAL</span><h1>${p[0]}</h1><h2>${p[1]}</h2><p>${p[2]}</p><p>${p[3]}</p><a class="button dark" href="${slug==='contact'?'/track-order':'/collections/all'}">${slug==='contact'?'Track an order':'Explore the collection'} ${icon('arrow')}</a></div>${['about','store'].includes(slug)?`<img src="/assets/${slug==='about'?'about':'store'}-reference.jpg" alt="Cricket Central store">`:''}</section>`;}
const orderStatusLabels={placed:'Placed',in_progress:'In progress',cancelled:'Cancelled',shipped:'Shipped',delivered:'Delivered'};
function orderTimeline(o){return `<ol class="order-timeline">${(o.history||[]).map(h=>`<li><b>${esc(orderStatusLabels[h.statusCode]||h.statusCode)}</b><span>${new Date(h.at).toLocaleString()}</span></li>`).join('')}</ol>`;}
function accountPage(){
 if(store.user)return `<section class="section account-section"><div class="section-heading"><div><span class="eyebrow">YOUR CRICKET CENTRAL ACCOUNT</span><h1>Welcome, ${esc(store.user.name)}.</h1><p>${esc(store.user.email)}</p></div><button class="button dark" data-action="customer-logout">Sign out</button></div><p><a class="button dark" href="/wishlist">Your saved items ${icon('heart')}</a></p><div class="profile-layout"><div><h2>Your profile</h2><p class="muted">Keep your contact and delivery details up to date.</p><form id="profile-form"><label>Full name<input name="name" autocomplete="name" value="${esc(store.user.name)}" maxlength="100" required></label><label>Email address<input value="${esc(store.user.email)}" disabled></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" value="${esc(store.user.phone||'')}" maxlength="25" required></label><label>Street address<input name="address" autocomplete="street-address" value="${esc(store.user.address||'')}" maxlength="190" required></label><div class="form-grid"><label>City<input name="city" value="${esc(store.user.city||'')}" maxlength="100" required></label><label>State<input name="state" value="${esc(store.user.state||'')}" maxlength="100" required></label><label>ZIP code<input name="zip" value="${esc(store.user.zip||'')}" pattern="[0-9]{5}(-[0-9]{4})?" required></label></div><p class="form-error" role="alert"></p><button class="button dark">Save profile ${icon('check')}</button></form></div><aside><h2>Your orders</h2><div id="account-orders" aria-live="polite"><p>Loading your orders…</p></div></aside></div><details class="claim-order"><summary>Add a past guest order</summary><p>Use an order placed with ${esc(store.user.email)}.</p><form id="claim-form"><label>Order number<input name="number" placeholder="CC-…" required></label><p class="form-error" role="alert"></p><button class="button dark">Add to my orders</button></form></details></section>`;
 const register=location.pathname==='/account/register',next=accountDestination()==='/account'?'':'?next='+encodeURIComponent(accountDestination()==='/checkout'?'checkout':accountDestination()==='/wishlist'?'wishlist':accountDestination());
 return `<section class="section narrow"><span class="eyebrow">YOUR NEXT INNINGS STARTS HERE</span><h1>${register?'Join the club.':'Welcome back.'}</h1><p>${register?'Create an account to keep your orders and favorites in one place.':'Sign in to see your orders and saved favorites.'}</p><form id="account-form" data-mode="${register?'register':'login'}">${register?'<label>Your name<input name="name" autocomplete="name" maxlength="100" required></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" maxlength="25" required></label><label>Street address<input name="address" autocomplete="street-address" maxlength="190" required></label><div class="form-grid"><label>City<input name="city" autocomplete="address-level2" maxlength="100" required></label><label>State<input name="state" autocomplete="address-level1" maxlength="100" required></label><label>ZIP code<input name="zip" autocomplete="postal-code" pattern="[0-9]{5}(-[0-9]{4})?" required></label></div>':''}<label>Email address<input name="email" type="email" autocomplete="email" maxlength="190" required></label><label>Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="${register?'8':'1'}" maxlength="128" required></label>${register?'<small class="muted">Use at least 8 characters.</small>':''}<p class="form-error" role="alert"></p><button class="button dark">${register?'Create account':'Sign in'} ${icon('arrow')}</button></form><p><a href="/account/forgot-password">Forgot your password?</a></p><p>${register?'Already have an account?':'New to Cricket Central?'} <a class="underlined" href="/account/${register?'login':'register'}${next}">${register?'Sign in':'Create an account'}</a></p><a class="underlined" href="${accountDestination()==='/checkout'?'/checkout':'/track-order'}">${accountDestination()==='/checkout'?'Continue as guest':'Track a guest order'}</a></section>`;
}
async function loadAccountOrders(version){try{const result=await api('account/orders');if(version!==renderVersion)return;$('#account-orders').innerHTML=result.orders.length?result.orders.map(o=>`<article class="account-order"><div class="account-order-head"><div><a href="/order/${o.number}"><b>${esc(o.number)} ↗</b></a><small>${new Date(o.created).toLocaleDateString()}</small></div><span class="status-pill">${esc(o.status)}</span><strong>${money(o.total)}</strong></div><p>${o.items.map(i=>`${esc(i.name)} × ${i.quantity}`).join(' · ')}</p>${orderTimeline(o)}</article>`).join(''):'<div class="empty-state"><h2>Your first innings awaits.</h2><p>Orders placed while signed in will appear here. Add a past guest order below.</p><a class="button dark" href="/collections/all">Find your gear</a></div>';}catch(err){if(version!==renderVersion)return;$('#account-orders').innerHTML=`<p>${esc(err.message)}</p><a href="/account/login">Sign in again</a>`;}}

function notFound(){return `<section class="section empty-state"><span class="eyebrow">404 / OUTSIDE THE BOUNDARY</span><h1>This one’s gone wide.</h1><p>We couldn’t find that page.</p><a class="button dark" href="/">Back to the pavilion ${icon('arrow')}</a></section>`;}
let renderVersion=0;
async function render(){stopHomeBanner();stopBrandCarousel();const version=++renderVersion;$('#bag').close();let content;const path=location.pathname;if(path==='/wishlist'&&!store.user){navigate('/account/login?next=wishlist');return;}if(path==='/')content=home();else if(path==='/search'||(path.startsWith('/collections/')&&(['all','sale'].includes(path.split('/')[2])||store.categories.some(c=>c.slug===path.split('/')[2]))))content=collection();else if(path.startsWith('/products/'))content=product();else if(path==='/cart')content=cartPage();else if(path==='/checkout')content=checkout();else if(path==='/track-order')content=tracking();else if(['/account/forgot-password','/account/reset-password'].includes(path))content=recoveryPage();else if(path==='/account'||path==='/account/login'||path==='/account/register'){content=accountPage();if(store.user)loadAccountOrders(version);}else if(path==='/wishlist')content=`<section class="section"><span class="eyebrow">KEEP AN EYE ON THESE</span><h1>Your saved lineup.</h1>${saved.length?`<div class="product-grid">${store.products.filter(p=>saved.includes(p.id)).map(card).join('')}</div>`:'<div class="empty-state"><h2>A little room for your favorites.</h2><p>Tap a product’s heart to save it here.</p><a class="button dark" href="/collections/all">Find your favorites</a></div>'}</section>`;else if(path.startsWith('/pages/'))content=page();else if(path.startsWith('/order/')){content='<section class="section narrow"><p>Loading your order…</p></section>';api('orders/'+path.split('/').pop()).then(o=>{if(version===renderVersion){$('#main').innerHTML=`<section class="section narrow"><div class="confirmation-icon">${icon('check')}</div><span class="eyebrow">A GREAT START</span><h1>You’re in the lineup.</h1><p>Your order request has been received. Our team will contact you to confirm the details and arrange payment. Keep this order number for tracking.</p>${orderView(o)}<a class="button dark" href="/collections/all">Keep exploring ${icon('arrow')}</a></section>`;}}).catch(e=>{if(version===renderVersion)$('#main').innerHTML=`<section class="section narrow"><h1>Order unavailable</h1><p>${esc(e.message)}</p><a class="button dark" href="/track-order">Track with email</a></section>`;});}else content=notFound();$('#app').innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer();startBrandCarousel();startHomeBanner();document.title=path==='/'?'Cricket Central — Made for the game.':`${$('#main h1')?.textContent||'Your order'} | Cricket Central`;}

function homeBanner(){
 const categoryLink=slug=>store.categories.some(c=>c.slug===slug)?'/collections/'+slug:'/collections/all';
 const slides=[
 {eyebrow:'THE CRICKET CENTRAL COLLECTION',title:'Gear up.',accent:'Play hard.',description:'From the first ball to the final over. Find your next match-day essentials at Cricket Central.',href:'/collections/all',button:'Explore the collection',image:'cricket-central-kit-banner.png',alt:'Cricket Central navy and gold cricket equipment collection',style:'banner-kit'},
 {eyebrow:'BATTING ESSENTIALS',title:'Find your',accent:'sweet spot.',description:'Explore cricket bats and find your next partner at the crease.',href:categoryLink('bats'),button:'Explore cricket bats',image:'banners/batting-essentials.png',alt:'Willow cricket bat, batting gloves and red leather ball in navy and gold lighting',style:'banner-kit'},
 {eyebrow:'READY FOR THE CREASE',title:'Build your',accent:'match-day kit.',description:'Explore helmets and protection, and find the right fit for your next innings.',href:categoryLink('protection'),button:'Explore protection',image:'banners/protective-gear.png',alt:'Navy cricket helmet, white batting pads and gloves with a red cricket ball',style:'banner-kit'},
 {eyebrow:'FROM PRACTICE TO MATCH DAY',title:'Pack your kit.',accent:'Play your game.',description:'Find kit bags and essentials for your next training session or match.',href:categoryLink('bags'),button:'Explore kit bags',image:'banners/match-day-kit.png',alt:'Cricket kit bag, shoes and navy polo beside a practice ground at sunset',style:'banner-kit'}
 ];
 return `<section class="home-banner" aria-label="Cricket Central highlights" aria-roledescription="carousel">${slides.map((slide,i)=>`<div class="banner-slide" role="group" aria-roledescription="slide" aria-label="${i+1} of ${slides.length}" ${i?'hidden':''}><div class="banner-copy"><span class="eyebrow">${esc(slide.eyebrow)}</span><${i?'h2':'h1'}>${esc(slide.title)}<br><em>${esc(slide.accent)}</em></${i?'h2':'h1'}><p>${esc(slide.description)}</p><a class="button lime" href="${slide.href}">${esc(slide.button)} ${icon('arrow')}</a></div><img class="${slide.style}" src="/assets/${slide.image}" alt="${esc(slide.alt)}" width="1536" height="1024" ${i?'loading="lazy"':'fetchpriority="high"'}></div>`).join('')}<div class="banner-controls"><button type="button" data-banner-step="-1" aria-label="Previous banner">←</button><div class="banner-dots">${slides.map((_,i)=>`<button type="button" data-banner-index="${i}" aria-label="Show banner ${i+1}" ${i?'':'aria-current="true"'}></button>`).join('')}</div><button type="button" data-banner-step="1" aria-label="Next banner">→</button><button type="button" class="banner-pause">Pause</button></div></section>`;
}
let stopHomeBanner=()=>{};
function startHomeBanner(){
 const root=document.querySelector('.home-banner');if(!root)return;
 const slides=[...root.querySelectorAll('.banner-slide')],dots=[...root.querySelectorAll('[data-banner-index]')],pause=root.querySelector('.banner-pause'),motion=matchMedia('(prefers-reduced-motion: reduce)');let index=0,paused=motion.matches,hover=false;
 const label=()=>{pause.textContent=paused?'Play':'Pause';pause.setAttribute('aria-label',paused?'Start automatic banner rotation':'Pause automatic banner rotation');};
 const show=i=>{index=(i+slides.length)%slides.length;slides.forEach((slide,n)=>slide.hidden=n!==index);dots.forEach((dot,n)=>{if(n===index)dot.setAttribute('aria-current','true');else dot.removeAttribute('aria-current');});};
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b===pause){paused=!paused;label();}else if(b.dataset.bannerStep||b.dataset.bannerIndex!==undefined){paused=true;label();show(b.dataset.bannerIndex!==undefined?Number(b.dataset.bannerIndex):index+Number(b.dataset.bannerStep));}});
 root.addEventListener('mouseenter',()=>hover=true);root.addEventListener('mouseleave',()=>hover=false);
 root.addEventListener('focusin',()=>{paused=true;label();});
 const onMotion=()=>{if(motion.matches){paused=true;label();}};motion.addEventListener('change',onMotion);
 const timer=setInterval(()=>{if(!paused&&!hover&&!document.hidden)show(index+1);},6000);
 stopHomeBanner=()=>{clearInterval(timer);motion.removeEventListener('change',onMotion);};label();
}
let stopBrandCarousel=()=>{};
function startBrandCarousel(){
 const track=$('#brand-track');if(!track)return;
 const section=track.closest('section'),pause=$('#brand-pause'),motion=matchMedia('(prefers-reduced-motion: reduce)');
 let paused=motion.matches,hover=false,focused=false;
 const label=()=>{pause.textContent=paused?'Play':'Pause';pause.setAttribute('aria-label',paused?'Start automatic brand scrolling':'Pause automatic brand scrolling');};
 const move=direction=>{const max=track.scrollWidth-track.clientWidth;const step=track.firstElementChild.getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap);let target=track.scrollLeft+direction*step;if(target>max+2)target=0;if(target< -2)target=max;track.scrollTo({left:Math.max(0,Math.min(max,target)),behavior:motion.matches?'instant':'smooth'});};
 section.addEventListener('mouseenter',()=>hover=true);section.addEventListener('mouseleave',()=>hover=false);
 section.addEventListener('focusin',()=>focused=true);section.addEventListener('focusout',e=>focused=section.contains(e.relatedTarget));
 section.querySelectorAll('[data-brand-step]').forEach(button=>button.addEventListener('click',()=>move(Number(button.dataset.brandStep))));
 pause.addEventListener('click',()=>{paused=!paused;label();});
 track.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowLeft'?-1:1);}});
 const timer=setInterval(()=>{if(!paused&&!hover&&!focused&&!document.hidden)move(1);},2800);
 const onMotion=()=>{paused=motion.matches;label();};motion.addEventListener('change',onMotion);
 stopBrandCarousel=()=>{clearInterval(timer);motion.removeEventListener('change',onMotion);};label();
}
function navigate(url){history.pushState({},'',url);render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});}
document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!a.hash&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();navigate(a.pathname+a.search);return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='customer-logout'){try{await api('account/logout','POST',{});store.user=null;saved=[];navigate('/account/login');}catch(err){toast(err.message);}return;}if(action==='bag')return openBag();if(action==='close-bag')return $('#bag').close();if(action==='save'){
 if(!store.user){const p=store.products.find(p=>p.id===b.dataset.id);navigate('/account/login?next='+encodeURIComponent(p?'/products/'+p.slug:'wishlist'));toast('Sign in to save your favorites.');return;}
 const id=b.dataset.id;b.disabled=true;
 try{const result=await api('account/saved-items',saved.includes(id)?'DELETE':'PUT',{productId:id});saved=result.savedItems;store.user.savedItems=saved;
 document.querySelectorAll('[data-action="save"]').forEach(el=>{const selected=saved.includes(el.dataset.id);el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',selected);});
 toast(saved.includes(id)?'Added to your saved lineup.':'Removed from saved items.');if(location.pathname==='/wishlist')render();
 }catch(err){if(err.status===401){navigate('/account/login?next=wishlist');}toast(err.message);}finally{b.disabled=false;}return;
 }if(action==='quantity'){b.disabled=true;try{cart=await api('cart','PATCH',{key:b.dataset.key,quantity:Number(b.dataset.value)});if($('#bag').open)openBag();else render();document.querySelectorAll('.cart-count').forEach(el=>el.textContent=cart.count);}catch(err){toast(err.message);b.disabled=false;}}});
document.addEventListener('submit',async e=>{const form=e.target;e.preventDefault();if(form.classList.contains('search-form'))return navigate('/search?'+new URLSearchParams(new FormData(form)));if(form.id==='filters-form')return navigate(location.pathname+'?'+new URLSearchParams(new FormData(form)));const b=$('button[type="submit"],button:not([type])',form);const data=Object.fromEntries(new FormData(form));if(b)b.disabled=true;const errBox=$('.form-error',form);if(errBox)errBox.textContent='';try{if(form.id==='promotion-form'){cart=await api('cart/promotion','POST',data);render();}else if(form.id==='recovery-form'){if(form.dataset.mode==='reset-password')data.token=new URLSearchParams(location.search).get('token');const result=await api('account/'+form.dataset.mode,'POST',data);errBox.textContent=result.message;if(form.dataset.mode==='reset-password'){form.reset();history.replaceState({},'',location.pathname);}}else if(form.id==='profile-form'){const result=await api('account','PATCH',data);store.user=result.user;toast('Profile updated.');render();
 }else if(form.id==='account-form'){
 const result=await api('account/'+form.dataset.mode,'POST',data);store.user=result.user;saved=result.user.savedItems||[];navigate(accountDestination());
 }else if(form.id==='claim-form'){await api('account/claim','POST',data);toast('Guest order added to your account.');render();
 }else if(form.id==='product-form'){cart=await api('cart','POST',{id:form.dataset.id,option:data.option,quantity:Number(data.quantity)});document.querySelectorAll('.cart-count').forEach(el=>el.textContent=cart.count);openBag();}else if(form.id==='checkout-form'){const result=await api('orders','POST',{...data,requestId:checkoutId});checkoutId=crypto.randomUUID();const fresh=await api('store');store=fresh;cart=fresh.cart;navigate('/order/'+result.number);}else if(form.id==='newsletter-form'){const result=await api('newsletter','POST',data);form.reset();toast(result.message);}else if(form.id==='track-form'){$('#tracking-result').innerHTML=orderView(await api('track','POST',data));}else if(form.id==='finder-form'){let matches=store.products.filter(p=>p.category===(data.player==='junior'?'juniors':'bats')&&p.price<=Number(data.budget)*100);matches.sort((a,b)=>data.style==='power'?b.price-a.price:a.price-b.price);$('#finder-result').innerHTML=`<h2>Your next innings, sorted.</h2><p>${data.player==='junior'?'Start with a junior kit and confirm the correct size.':data.style==='power'?'Explore these bats within your budget, starting with the premium profiles.':'Explore these balanced options within your budget.'}</p><div class="product-grid finder-results">${matches.slice(0,2).map(card).join('')}</div><p class="muted">Recommendations use this demo catalog. Confirm bat weight, size, and specifications before purchase.</p>`;}}catch(err){if(errBox)errBox.textContent=err.message;else toast(err.message);}finally{if(b)b.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){const p=new URLSearchParams(location.search);p.set('sort',e.target.value);navigate(location.pathname+'?'+p);}});
$('#bag').addEventListener('click',e=>{if(e.target===$('#bag')){const r=$('#bag').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#bag').close();}});
window.addEventListener('popstate',render);
try{store=await api('store');cart=store.cart;csrf=store.csrf;saved=store.user?.savedItems||[];render();}catch(e){$('#app').innerHTML=`<main class="section empty-state"><h1>We’ll be right back.</h1><p>${esc(e.message)}</p><a class="button dark" href="/">Try again</a></main>`;}
